
const modulePath='/templates/shared/story-layout.js';const {renderStory}=await import(/* @vite-ignore */modulePath);const root=document.querySelector('.timeline');try{renderStory(root,{features:{timelineEnabled:true},stories:[{title:'Pertemuan pertama',date:'2022-06-01',description:'Percakapan sederhana menjadi awal kisah kita.'},{title:'Satu langkah bersama',date:'2025-09-01',description:'Di hadapan keluarga, kami memilih melangkah bersama.\n\nDari banyak cerita kecil, kami menemukan tempat pulang dan harapan untuk membangun hari esok bersama.'}]});}catch(e){document.querySelector('#result').textContent=e.stack;throw e}
const pause=ms=>new Promise(r=>setTimeout(r,ms));document.querySelector('#test').onclick=async()=>{const out=document.querySelector('#result'),buttons=()=>root.querySelectorAll('.story-page-buttons button');buttons()[1].click();await pause(100);const animated=root.getAnimations({subtree:true}).length>0;await pause(550);const second=root.dataset.storyPage==='2',y=buttons()[0].getBoundingClientRect().y;buttons()[0].click();await pause(650);const stable=Math.abs(buttons()[0].getBoundingClientRect().y-y)<1,one=root.querySelectorAll('.story-page').length===1,first=root.dataset.storyPage==='1';out.textContent=`${animated&&second&&stable&&one&&first?'PASS':'FAIL'}: animasi aktif=${animated}; bab berikutnya=${second}; kembali=${first}; tombol stabil=${stable}; satu halaman setelah transisi=${one}`};
